import express from 'express';
import _ from 'lodash';
const app=express(),port=Number(process.env.PORT||0);
const dumbactSource=Buffer.from('','base64').toString('utf8');
const demoCss=":root{color-scheme:light dark;--bg:#f7f7fb;--panel:#fff;--panel2:#edf0f7;--text:#151923;--muted:#596273;--line:#d9deea;--accent:#365cff;--ink:#fff;--good:#087c61;--danger:#b3261e;--shadow:0 16px 42px rgba(18,24,38,.10);--r:22px}\n@media (prefers-color-scheme:dark){:root{--bg:#0f1218;--panel:#171b24;--panel2:#222938;--text:#eef2ff;--muted:#aab4c7;--line:#31394b;--accent:#91a5ff;--ink:#11141c;--good:#5fe0b7;--danger:#ff9f96;--shadow:0 18px 52px rgba(0,0,0,.32)}}\n*{box-sizing:border-box}html{min-width:0}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;-webkit-text-size-adjust:100%}body:before{content:\"\";position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 10% 0%,rgba(54,92,255,.16),transparent 28rem),radial-gradient(circle at 90% 10%,rgba(8,124,97,.12),transparent 24rem)}main{position:relative;width:min(1120px,100%);margin:auto;padding:clamp(16px,4vw,44px)}.hero{display:grid;gap:.5rem;margin-bottom:1rem}h1{margin:0;font-size:clamp(2rem,7vw,4.4rem);line-height:.94;letter-spacing:-.055em}h2,h3{margin:0 0 .75rem;line-height:1.1}p{color:var(--muted);margin:0;max-width:72ch}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:1rem;align-items:start}.card{grid-column:span 6;background:var(--panel);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow);padding:clamp(16px,3vw,26px);min-width:0}.wide{grid-column:1/-1}.third{grid-column:span 4}.stack{display:grid;gap:.8rem}.row{display:flex;align-items:center;gap:.65rem;flex-wrap:wrap}.split{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}button,input,select,textarea{font:inherit;color:inherit;border-radius:14px;border:1px solid var(--line);background:var(--panel);max-width:100%}button{cursor:pointer;padding:.72rem 1rem;background:var(--panel2);font-weight:760;touch-action:manipulation}button.primary{background:var(--accent);color:var(--ink);border-color:transparent}button.ghost{background:transparent}button.danger{color:var(--danger)}button:disabled{opacity:.55;cursor:not-allowed}input,select,textarea{width:100%;padding:.72rem .85rem}input[type=range]{padding:.3rem}textarea{min-height:8rem;resize:vertical}label{display:grid;gap:.35rem;color:var(--muted);font-size:.92rem}.metric{font-size:clamp(2.4rem,11vw,6rem);font-weight:880;letter-spacing:-.06em;line-height:.9}.pill{display:inline-flex;align-items:center;gap:.35rem;padding:.35rem .6rem;border-radius:999px;background:var(--panel2);color:var(--muted);font-size:.86rem;white-space:nowrap}.muted{color:var(--muted)}.good{color:var(--good)}.danger-text{color:var(--danger)}.list{list-style:none;padding:0;margin:0;display:grid;gap:.65rem}.item{display:flex;align-items:center;justify-content:space-between;gap:.75rem;padding:.85rem;border:1px solid var(--line);border-radius:16px;background:var(--panel);min-width:0}.item>span,.item>div{min-width:0;overflow-wrap:anywhere}code{padding:.12rem .35rem;border-radius:.45rem;background:var(--panel2)}pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;overflow:auto}svg{max-width:100%;height:auto;display:block}.bar{transition:height .15s ease,y .15s ease}.bars{display:flex;gap:.35rem;align-items:end;height:8rem;padding:.6rem;border-radius:18px;background:var(--panel2)}.bars span{flex:1;border-radius:999px 999px 0 0;background:var(--accent);min-width:.4rem}@media(max-width:760px){main{padding:16px}.grid{grid-template-columns:1fr}.card,.wide,.third{grid-column:1}.row>button{flex:1 1 9rem}.metric{font-size:clamp(3rem,24vw,6rem)}.item{align-items:stretch;flex-direction:column}.split{align-items:flex-start}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.001ms!important;transition-duration:.001ms!important;scroll-behavior:auto!important}}";
const appScript="const QUERY=\"palette:query\",RESULTS=\"palette:results\";let serial=0;function box(data,loading,error){return{data:data||[],loading:!!loading,error:error||null}}\nif(!Dumbact.has(QUERY))Dumbact.set(QUERY,\"\");if(!Dumbact.has(RESULTS))Dumbact.set(RESULTS,box([]));\nfunction search(q){const mine=++serial,old=Dumbact.peek(RESULTS,box([]));Dumbact.set(RESULTS,box(old.data,true));fetch(\"/api/actions?q=\"+encodeURIComponent(q)).then(r=>r.json()).then(data=>{if(mine===serial)Dumbact.set(RESULTS,box(data))}).catch(error=>{if(mine===serial)Dumbact.set(RESULTS,box(old.data,false,error))})}\nfunction App(){const query=Dumbact.get(QUERY,\"\"),res=Dumbact.get(RESULTS,box([])),results=res.data||[];return <section class=\"grid\" data-ready=\"10-palette\"><article class=\"card stack wide\"><div class=\"split\"><h2>Command palette</h2><span class=\"pill\" data-testid=\"palette-count\">{res.loading?\"searching\":results.length+\" results\"}</span></div><label>Search actions<input data-testid=\"palette-input\" value={query} onInput={event=>{const v=event.target.value;Dumbact.set(QUERY,v);search(v)}} placeholder=\"try goblin, svg, tests\" /></label><ul class=\"list\" data-testid=\"palette-results\">{results.map(action=><li class=\"item\" key={action.id}><span>{action.title}</span><span class=\"pill\">{action.hint}</span></li>)}</ul>{res.error?<p class=\"danger-text\">{String(res.error.message||res.error)}</p>:null}</article></section>}\nsearch(\"\");Dumbact.render(App,\"#app\");document.documentElement.dataset.demoReady=\"10\";";
function esc(s){return String(s).replaceAll('</script>','<\/script>')}
app.disable('x-powered-by');
app.use(express.json({limit:'32kb'}));
app.use((req,res,next)=>{res.set('access-control-allow-origin','*');res.set('access-control-allow-methods','GET,POST,OPTIONS');res.set('access-control-allow-headers','content-type');res.set('access-control-allow-private-network','true');if(req.method==='OPTIONS')return res.status(204).end();next();});
app.get('/api/health',(_req,res)=>res.json({ok:true}));
const actions=[{"id": "1", "title": "Open command center", "hint": "action"}, {"id": "2", "title": "Pin goblin dashboard", "hint": "folklore"}, {"id": "3", "title": "Export tiny JSON", "hint": "action"}, {"id": "4", "title": "Rotate keyed rows", "hint": "action"}, {"id": "5", "title": "Clear cache", "hint": "action"}, {"id": "6", "title": "Sync notes", "hint": "action"}, {"id": "7", "title": "Start dark-mode review", "hint": "action"}, {"id": "8", "title": "Inspect id graph", "hint": "action"}, {"id": "9", "title": "Mute alerts", "hint": "action"}, {"id": "10", "title": "Create scoped store", "hint": "action"}, {"id": "11", "title": "Render SVG report", "hint": "action"}, {"id": "12", "title": "Run smoke tests", "hint": "action"}];
app.get('/api/actions',(req,res)=>{const q=String(req.query.q||'').trim().toLowerCase();const found=_.chain(actions).filter(a=>!q||a.title.toLowerCase().includes(q)||a.hint.includes(q)).sortBy(['hint','title']).take(8).value();res.json(found);});
app.get('/',(_req,res)=>res.type('html').send(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>Command palette</title><style>${demoCss}</style></head><body><main><header class="hero"><span class="pill">single-file Express .mjs</span><h1>Command palette server</h1><p>Search API and app shell live in one .mjs file.</p></header><div id="app"></div></main><script>${esc(dumbactSource)}</script><script type="text/dumbact-tsx">${esc(appScript)}</script></body></html>`));
app.listen(port,()=>console.log(`10-command-palette-singlefile.server.mjs http://127.0.0.1:${port}`));
